class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def max_depth(root):
    """
    Returns the maximum depth of a binary tree.
    Depth of an empty tree = 0
    """
    if root is None:
        return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))
